{"command":"cat << 'EOF' > src/formatters.py
import json

def is_numeric_type(typ):
    typ_lower = str(typ).lower()
    return any(t in typ_lower for t in ["int", "float", "double", "decimal", "hugeint", "numeric", "real"])

def format_duckbox(columns, rows, col_types, opts):
    if not columns:
        return ""

    num_cols = len(columns)
    null_str = opts.nullvalue

    total_rows = len(rows)
    truncated = total_rows > 40
    if truncated:
        display_rows = rows[:20] + [None] + rows[-20:]
    else:
        display_rows = rows

    col_widths = []
    for i in range(num_cols):
        col_name = str(columns[i])
        col_type = str(col_types[i]) if col_types and i < len(col_types) else ""
        max_len = max(len(col_name), len(col_type))

        for row in rows:
            if row is None:
                continue
            val = row[i]
            if val is None:
                v_str = null_str
            elif isinstance(val, bool):
                v_str = "true" if val else "false"
            else:
                v_str = str(val)
            if len(v_str) > max_len:
                max_len = len(v_str)

        col_widths.append(max_len + 2)

    out = []

    # Top border
    top = "┌" + "┬".join("─" * w for w in col_widths) + "┐"
    out.append(top)

    # Header line 1 (names)
    name_cells = []
    for i in range(num_cols):
        col_name = str(columns[i])
        w = col_widths[i]
        content_w = w - 2
        pad = content_w - len(col_name)
        left = pad // 2
        right = pad - left
        name_cells.append(" " * (1 + left) + col_name + " " * (1 + right))
    out.append("│" + "│".join(name_cells) + "│")

    # Header line 2 (types)
    type_cells = []
    for i in range(num_cols):
        col_type = str(col_types[i]) if col_types and i < len(col_types) else ""
        w = col_widths[i]
        content_w = w - 2
        pad = content_w - len(col_type)
        left = pad // 2
        right = pad - left
        type_cells.append(" " * (1 + left) + col_type + " " * (1 + right))
    out.append("│" + "│".join(type_cells) + "│")

    if display_rows:
        sep = "├" + "┼".join("─" * w for w in col_widths) + "┤"
        out.append(sep)

        for row in display_rows:
            if row is None:
                dots = []
                for i in range(num_cols):
                    w = col_widths[i]
                    content_w = w - 2
                    pad = content_w - 1
                    left = pad // 2
                    right = pad - left
                    dots.append(" " * (1 + left) + "·" + " " * (1 + right))
                out.append("│" + "│".join(dots) + "│")
                continue

            val_cells = []
            for i in range(num_cols):
                val = row[i]
                is_num = is_numeric_type(col_types[i] if col_types and i < len(col_types) else "")
                if val is None:
                    v_str = null_str
                elif isinstance(val, bool):
                    v_str = "true" if val else "false"
                else:
                    v_str = str(val)

                w = col_widths[i]
                content_w = w - 2
                pad = content_w - len(v_str)

                if is_num:
                    val_cells.append(" " * (1 + pad) + v_str + " ")
                else:
                    val_cells.append(" " + v_str + " " * (1 + pad))
            out.append("│" + "│".join(val_cells) + "│")

    bot = "└" + "┴".join("─" * w for w in col_widths) + "┘"
    out.append(bot)

    table_width = sum(col_widths) + num_cols + 1
    if total_rows == 0:
        text = "0 rows"
        pad = table_width - len(text)
        left = pad // 2
        right = pad - left
        out.append(" " * left + text + " " * right)
    elif truncated:
        t1 = f"{total_rows} rows"
        pad1 = table_width - len(t1)
        left1 = pad1 // 2
        right1 = pad1 - left1
        out.append(" " * left1 + t1 + " " * right1)

        t2 = "(40 shown)"
        pad2 = table_width - len(t2)
        left2 = pad2 // 2
        right2 = pad2 - left2
        out.append(" " * left2 + t2 + " " * right2)

    return "\n".join(out)

def format_box(columns, rows, col_types, opts):
    if not columns:
        return ""
    num_cols = len(columns)
    null_str = opts.nullvalue

    col_widths = []
    for i in range(num_cols):
        max_len = len(str(columns[i]))
        for row in rows:
            val = row[i]
            v_str = null_str if val is None else ("true" if isinstance(val, bool) and val is True else ("false" if isinstance(val, bool) and val is False else str(val)))
            if len(v_str) > max_len:
                max_len = len(v_str)
        col_widths.append(max_len + 2)

    out = []
    out.append("┌" + "┬".join("─" * w for w in col_widths) + "┐")

    name_cells = []
    for i in range(num_cols):
        col_name = str(columns[i])
        w = col_widths[i]
        content_w = w - 2
        pad = content_w - len(col_name)
        left = pad // 2
        right = pad - left
        name_cells.append(" " * (1 + left) + col_name + " " * (1 + right))
    out.append("│" + "│".join(name_cells) + "│")

    out.append("├" + "┼".join("─" * w for w in col_widths) + "┤")

    for row in rows:
        val_cells = []
        for i in range(num_cols):
            val = row[i]
            v_str = null_str if val is None else ("true" if isinstance(val, bool) and val is True else ("false" if isinstance(val, bool) and val is False else str(val)))
            w = col_widths[i]
            content_w = w - 2
            pad = content_w - len(v_str)
            val_cells.append(" " + v_str + " " * (1 + pad))
        out.append("│" + "│".join(val_cells) + "│")

    out.append("└" + "┴".join("─" * w for w in col_widths) + "┘")
    return "\n".join(out)

def format_table(columns, rows, col_types, opts):
    if not columns:
        return ""
    num_cols = len(columns)
    null_str = opts.nullvalue

    col_widths = []
    for i in range(num_cols):
        max_len = len(str(columns[i]))
        for row in rows:
            val = row[i]
            v_str = null_str if val is None else ("true" if isinstance(val, bool) and val is True else ("false" if isinstance(val, bool) and val is False else str(val)))
            if len(v_str) > max_len:
                max_len = len(v_str)
        col_widths.append(max_len + 2)

    out = []
    out.append("+" + "+".join("-" * w for w in col_widths) + "+")

    name_cells = []
    for i in range(num_cols):
        col_name = str(columns[i])
        w = col_widths[i]
        content_w = w - 2
        pad = content_w - len(col_name)
        left = pad // 2
        right = pad - left
        name_cells.append(" " * (1 + left) + col_name + " " * (1 + right))
    out.append("|" + "|".join(name_cells) + "|")

    out.append("+" + "+".join("-" * w for w in col_widths) + "+")

    for row in rows:
        val_cells = []
        for i in range(num_cols):
            val = row[i]
            v_str = null_str if val is None else ("true" if isinstance(val, bool) and val is True else ("false" if isinstance(val, bool) and val is False else str(val)))
            w = col_widths[i]
            content_w = w - 2
            pad = content_w - len(v_str)
            val_cells.append(" " + v_str + " " * (1 + pad))
        out.append("|" + "|".join(val_cells) + "|")

    out.append("+" + "+".join("-" * w for w in col_widths) + "+")
    return "\n".join(out)

def format_column(columns, rows, col_types, opts):
    if not columns:
        return ""
    num_cols = len(columns)
    null_str = opts.nullvalue

    col_widths = []
    for i in range(num_cols):
        max_len = len(str(columns[i]))
        for row in rows:
            val = row[i]
            v_str = null_str if val is None else ("true" if isinstance(val, bool) and val is True else ("false" if isinstance(val, bool) and val is False else str(val)))
            if len(v_str) > max_len:
                max_len = len(v_str)
        col_widths.append(max_len)

    out = []
    if opts.headers:
        out.append("  ".join(str(columns[i]).ljust(col_widths[i]) for i in range(num_cols)) + " ")
        out.append("  ".join("-" * col_widths[i] for i in range(num_cols)) + " ")

    for row in rows:
        cells = []
        for i in range(num_cols):
            val = row[i]
            v_str = null_str if val is None else ("true" if isinstance(val, bool) and val is True else ("false" if isinstance(val, bool) and val is False else str(val)))
            cells.append(v_str.ljust(col_widths[i]))
        out.append("  ".join(cells) + " ")

    return "\n".join(out)

def format_csv(columns, rows, col_types, opts):
    out = []
    sep = opts.colseparator
    null_str = opts.nullvalue

    if opts.headers and columns:
        out.append(sep.join(str(c) for c in columns))

    for row in rows:
        cells = []
        for val in row:
            if val is None:
                cells.append(null_str)
            elif isinstance(val, bool):
                cells.append("true" if val else "false")
            else:
                cells.append(str(val))
        out.append(sep.join(cells))

    return "\n".join(out)

def format_list(columns, rows, col_types, opts):
    return format_csv(columns, rows, col_types, opts)

def format_json(columns, rows, col_types, opts):
    records = []
    for row in rows:
        rec = {}
        for col, val in zip(columns, row):
            if isinstance(val, bool):
                rec[col] = val
            elif val is None:
                rec[col] = None
            else:
                rec[col] = val
        records.append(rec)
    if not records:
        return "[]"
    lines = [json.dumps(records[0], separators=(',', ':'))]
    for r in records[1:]:
        lines.append(json.dumps(r, separators=(',', ':')))
    return "[" + ",\n".join(lines) + "]"

def format_jsonlines(columns, rows, col_types, opts):
    lines = []
    for row in rows:
        rec = {}
        for col, val in zip(columns, row):
            rec[col] = val
        lines.append(json.dumps(rec, separators=(',', ':')))
    return "\n".join(lines)

def format_markdown(columns, rows, col_types, opts):
    if not columns:
        return ""
    num_cols = len(columns)
    null_str = opts.nullvalue

    col_widths = []
    for i in range(num_cols):
        max_len = len(str(columns[i]))
        for row in rows:
            val = row[i]
            v_str = null_str if val is None else ("true" if isinstance(val, bool) and val is True else ("false" if isinstance(val, bool) and val is False else str(val)))
            if len(v_str) > max_len:
                max_len = len(v_str)
        col_widths.append(max_len)

    out = []
    # Header
    name_cells = []
    for i in range(num_cols):
        col_name = str(columns[i])
        w = col_widths[i]
        is_num = is_numeric_type(col_types[i] if col_types and i < len(col_types) else "")
        if is_num:
            name_cells.append(" " + col_name.rjust(w) + " ")
        else:
            name_cells.append(" " + col_name.center(w) + " ")
    out.append("|" + "|".join(name_cells) + "|")

    # Separator
    sep_cells = []
    for i in range(num_cols):
        w = col_widths[i]
        is_num = is_numeric_type(col_types[i] if col_types and i < len(col_types) else "")
        if is_num:
            sep_cells.append("-" * (w + 1) + ":")
        else:
            sep_cells.append("-" * (w + 2))
    out.append("|" + "|".join(sep_cells) + "|")

    for row in rows:
        val_cells = []
        for i in range(num_cols):
            val = row[i]
            is_num = is_numeric_type(col_types[i] if col_types and i < len(col_types) else "")
            v_str = null_str if val is None else ("true" if isinstance(val, bool) and val is True else ("false" if isinstance(val, bool) and val is False else str(val)))
            w = col_widths[i]
            if is_num:
                val_cells.append(" " + v_str.rjust(w) + " ")
            else:
                val_cells.append(" " + v_str.ljust(w) + " ")
        out.append("|" + "|".join(val_cells) + "|")

    return "\n".join(out)

def format_html(columns, rows, col_types, opts):
    out = []
    if columns:
        out.append("<tr>" + "".join(f"<th>{c}</th>\n" for c in columns) + "</tr>")
    for row in rows:
        out.append("<tr>" + "".join(f"<td>{opts.nullvalue if v is None else ('true' if v is True else ('false' if v is False else v))}</td>\n" for v in row) + "</tr>")
    return "".join(out).rstrip("\n")

def format_ascii(columns, rows, col_types, opts):
    out = []
    if opts.headers and columns:
        for c in columns:
            out.append(str(c))
    for row in rows:
        for v in row:
            out.append(opts.nullvalue if v is None else ("true" if v is True else ("false" if v is False else str(v))))
    return "\n".join(out)

def format_quote(columns, rows, col_types, opts):
    sep = opts.colseparator
    null_str = opts.nullvalue
    out = []
    if opts.headers and columns:
        out.append(sep.join(f"'{c}'" for c in columns))
    for row in rows:
        cells = []
        for val in row:
            if val is None:
                cells.append(null_str)
            elif isinstance(val, (int, float)) and not isinstance(val, bool):
                cells.append(str(val))
            elif isinstance(val, bool):
                cells.append("true" if val else "false")
            else:
                cells.append(f"'{val}'")
        out.append(sep.join(cells))
    return "\n".join(out)

def format_line(columns, rows, col_types, opts):
    if not columns or not rows:
        return ""
    max_col_len = max(len(str(c)) for c in columns)
    out = []
    for r_idx, row in enumerate(rows):
        if r_idx > 0:
            out.append("")
        for col, val in zip(columns, row):
            v_str = opts.nullvalue if val is None else ("true" if isinstance(val, bool) and val is True else ("false" if isinstance(val, bool) and val is False else str(val)))
            out.append(f"{str(col).rjust(max_col_len)} = {v_str}")
    return "\n".join(out)

def format_insert(columns, rows, col_types, opts, table_name="table_name"):
    out = []
    cols_str = ",".join(str(c) for c in columns)
    for row in rows:
        vals = []
        for val in row:
            if val is None:
                vals.append("NULL")
            elif isinstance(val, (int, float)) and not isinstance(val, bool):
                vals.append(str(val))
            elif isinstance(val, bool):
                vals.append("true" if val else "false")
            else:
                vals.append(f"'{val}'")
        out.append(f"INSERT INTO {table_name}({cols_str}) VALUES({','.join(vals)});")
    return "\n".join(out)

def format_results(columns, rows, col_types, opts, table_name="table_name"):
    mode = opts.mode.lower()
    if mode == "duckbox":
        return format_duckbox(columns, rows, col_types, opts)
    elif mode == "box":
        return format_box(columns, rows, col_types, opts)
    elif mode == "table":
        return format_table(columns, rows, col_types, opts)
    elif mode == "column":
        return format_column(columns, rows, col_types, opts)
    elif mode in ("csv", "list", "tabs"):
        return format_csv(columns, rows, col_types, opts)
    elif mode == "json":
        return format_json(columns, rows, col_types, opts)
    elif mode == "jsonlines":
        return format_jsonlines(columns, rows, col_types, opts)
    elif mode == "markdown":
        return format_markdown(columns, rows, col_types, opts)
    elif mode == "html":
        return format_html(columns, rows, col_types, opts)
    elif mode == "ascii":
        return format_ascii(columns, rows, col_types, opts)
    elif mode == "quote":
        return format_quote(columns, rows, col_types, opts)
    elif mode == "line":
        return format_line(columns, rows, col_types, opts)
    elif mode == "insert":
        return format_insert(columns, rows, col_types, opts, table_name)
    elif mode == "trash":
        return ""
    else:
        return format_duckbox(columns, rows, col_types, opts)
