    sep = opts.colseparator
    null_str = opts.nullvalue
    out = []
    if opts.headers and columns:
        out.append(sep.join(f"'{c}'" for c in columns))
    for row in rows:
        cells = []
        for val in row:
            if val is None:
                cells.append(null_str)
            elif isinstance(val, (int, float)) and not isinstance(val, bool):
                cells.append(str(val))
            elif isinstance(val, bool):
                cells.append("true" if val else "false")
            else:
                cells.append(f"'{val}'")
        out.append(sep.join(cells))
    return "\n".join(out)

def format_line(columns, rows, col_types, opts):
    if not columns or not rows:
        return ""
    max_col_len = max(len(str(c)) for c in columns)
    out = []
    for r_idx, row in enumerate(rows):
        if r_idx > 0:
            out.append("")
        for col, val in zip(columns, row):
            v_str = opts.nullvalue if val is None else ("true" if isinstance(val, bool) and val is True else ("false" if isinstance(val, bool) and val is False else str(val)))
            out.append(f"{str(col).rjust(max_col_len)} = {v_str}")
