    mode = opts.mode.lower()
    if mode == "duckbox":
        return format_duckbox(columns, rows, col_types, opts)
    elif mode == "box":
        return format_box(columns, rows, col_types, opts)
    elif mode == "table":
        return format_table(columns, rows, col_types, opts)
    elif mode == "column":
        return format_column(columns, rows, col_types, opts)
    elif mode in ("csv", "list", "tabs"):
        return format_csv(columns, rows, col_types, opts)
    elif mode == "json":
        return format_json(columns, rows, col_types, opts)
    elif mode == "jsonlines":
        return format_jsonlines(columns, rows, col_types, opts)
    elif mode == "markdown":
        return format_markdown(columns, rows, col_types, opts)
    elif mode == "html":
        return format_html(columns, rows, col_types, opts)
    elif mode == "ascii":
        return format_ascii(columns, rows, col_types, opts)
    elif mode == "quote":
        return format_quote(columns, rows, col_types, opts)
    elif mode == "line":
        return format_line(columns, rows, col_types, opts)
    elif mode == "insert":
        return format_insert(columns, rows, col_types, opts, table_name)
    elif mode == "trash":
        return ""
    else:
        return format_duckbox(columns, rows, col_types, opts)
