import sys
import os
from src.options import parse_args, VERSION_STRING
from src.engine import Engine
from src.formatters import format_results
from src.dot_commands import handle_dot_command

def execute_statement(stmt, opts, engine, output_target):
    stmt = stmt.strip()
    if not stmt:
        return

    if opts.echo:
        output_target.write(stmt + "\n")

    if stmt.startswith("."):
        handle_dot_command(stmt, opts, engine, output_target)
        return

    try:
        columns, rows, col_types = engine.execute(stmt)
        if columns is not None:
            res = format_results(columns, rows, col_types, opts)
            if res:
                output_target.write(res + "\n")
    except PermissionError as pe:
        sys.stderr.write(f"Invalid Input Error: {pe}\n")
        if opts.bail:
            sys.exit(1)
    except Exception as e:
        err_msg = str(e)
        if "no such table" in err_msg or "does not exist" in err_msg:
            sys.stderr.write(f"Catalog Error: {err_msg}\n")
        elif "syntax error" in err_msg or "Parse" in err_msg:
            sys.stderr.write(f"Parser Error: {err_msg}\n")
        else:
            sys.stderr.write(f"Binder Error: {err_msg}\n")

        sys.exit(1)

def process_file_or_string(content, opts, engine, output_target):
    # Split content into statements by semicolon, but keeping dot commands on own lines
    lines = content.splitlines()
    current_sql = []

    for line in lines:
        line_str = line.strip()
        if not line_str:
            continue

        if line_str.startswith("."):
            if current_sql:
                execute_statement(" ".join(current_sql), opts, engine, output_target)
                current_sql = []
            execute_statement(line_str, opts, engine, output_target)
        else:
            current_sql.append(line)
            if line_str.endswith(";"):
                execute_statement("\n".join(current_sql), opts, engine, output_target)
                current_sql = []

    if current_sql:
        execute_statement("\n".join(current_sql), opts, engine, output_target)

def main():
    opts = parse_args(sys.argv[1:])
    engine = Engine(opts.filename, opts.readonly)
    output_target = sys.stdout

    # Process init file
    if not opts.no_init:
        init_path = opts.init_file
        if not init_path:
            duckdbrc = os.path.expanduser("~/.duckdbrc")
            if os.path.exists(duckdbrc):
                init_path = duckdbrc

        if init_path and os.path.exists(init_path):
            output_target.write(f"\x1b[90m-- Loading resources from {init_path}\n\x1b[00m")
            with open(init_path, 'r', encoding='utf-8', errors='ignore') as f:
                process_file_or_string(f.read(), opts, engine, output_target)

    # Process -cmd commands
    for cmd in opts.cmd_commands:
        process_file_or_string(cmd, opts, engine, output_target)

    # Process main commands or positional SQLs
    all_main = opts.main_commands + opts.positional_sqls
    if all_main:
        for cmd in all_main:
            process_file_or_string(cmd, opts, engine, output_target)
        sys.exit(0)

    if opts.no_stdin:
        sys.exit(0)

    # Read from stdin
    if not sys.stdin.isatty() or opts.batch:
        content = sys.stdin.read()
        if content:
            process_file_or_string(content, opts, engine, output_target)
